3	/**
4	 * The single definition of the <em>Luhn check digit</em>: the digit (0-9) that, appended to
5	 * a sequence of digits, makes the whole pass the Luhn checksum. Non-digit characters in the
6	 * input are ignored, so it can be computed directly over a formatted value such as a
7	 * {@link CustomerCode}.
8	 *
9	 * <p>Pure function of its input; the digit is computed on read rather than stored.
10	 */
11	public final class Luhn {
12	
13	    private Luhn() {
14	    }
15	
16	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
17	    public static int checkDigit(String value) {
18	        int sum = 0;
19	        boolean doubled = true;
20	        for (int i = value.length() - 1; i >= 0; i--) {
21	            char c = value.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int digit = c - '0';
26	            if (doubled) {
27	                digit *= 2;
28	                if (digit > 9) {
29	                    digit -= 9;
30	                }
31	            }
32	            sum += digit;
33	            doubled = !doubled;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
