1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Step of {@code POST /api/owners}: assigns the new owner's {@code membershipLevel} — a
8	 * number from 1 to 3 fixed at registration. It starts at 1, gains a level when the owner
9	 * has an email on file and another when the owner has no namesakes ({@code namesakeCount}
10	 * is 0), and is capped at 3 (level 4 is reserved for tenure). It runs after
11	 * {@link CountNamesakes} so the namesake count is known, and before {@link SaveOwner}
12	 * persists the owner and {@link AuditOwnerCreated} records the level. The value is stored
13	 * with the row and returned unchanged on later reads.
14	 */
15	public class AssignMembershipLevel {
16	
17	    /** The highest level the registration rules award; level 4 is reserved for tenure. */
18	    private static final int MAX_LEVEL = 3;
19	
20	    public void service(@Val Owner owner) {
21	        int level = 1;
22	        String email = owner.getEmail();
23	        if (email != null && !email.isBlank()) {
24	            level++;
25	        }
26	        Integer namesakeCount = owner.getNamesakeCount();
27	        if (namesakeCount != null && namesakeCount == 0) {
28	            level++;
29	        }
30	        owner.setMembershipLevel(Math.min(level, MAX_LEVEL));
31	    }
32	}
