65	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
66	     *  customer code has been assigned. */
67	    default Integer checkDigit(Owner owner) {
68	        String customerCode = owner.getCustomerCode();
69	        return customerCode == null ? null : Luhn.checkDigit(customerCode);
70	    }
71	
72	    /** The owner's region, derived from its postcode range first (NSW 2000-2099, VIC 3000-3099,
73	     *  QLD 4000-4099), falling back to the city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
74	     *  Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
75	    default String locality(Owner owner) {
76	        return Locality.region(owner.getCity(), owner.getPostcode());
77	    }
78	
79	    /** The owner's preferred contact channel: 'EMAIL' when an email address is on file,
80	     *  otherwise 'PHONE'. */
81	    default String contactPreference(Owner owner) {
82	        String email = owner.getEmail();
83	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
84	    }
85	
86	    Owner toOwner(OwnerDto ownerDto);
87	
88	    @Mapping(target = "id", ignore = true)
89	    @Mapping(target = "pets", ignore = true)
90	    Owner toOwner(OwnerFieldsDto ownerDto);
91	
92	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
93	
94	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
95	
96	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
97	        OwnerPageDto ownerPageDto = new OwnerPageDto();
98	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
99	        ownerPageDto.setPage(ownerPage.getNumber());
100	        ownerPageDto.setSize(ownerPage.getSize());
101	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
102	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
103	        return ownerPageDto;
104	    }
105	}
